-- MIMU — PostgreSQL 15+ base schema for MVP v1.3
-- IDs: generated by the application using a vetted UUIDv7 implementation.
-- MVP v1.3: Home scoped to the selected student, manual grade publication,
-- immediate updates to published grades and educator-controlled tasks.
-- Deferred from the active schema: support tickets, advanced audit, push tokens, outbox,
-- advanced grading weights/configuration, and seed data.
-- Apply through versioned migrations using a least-privileged migration role.
BEGIN;

CREATE SCHEMA IF NOT EXISTS mimu;
SET search_path TO mimu, public;

CREATE TYPE account_status AS ENUM ('INVITED','ACTIVE','SUSPENDED','LOCKED','DEACTIVATED');
CREATE TYPE institution_status AS ENUM ('ACTIVE','SUSPENDED','CLOSED');
CREATE TYPE membership_status AS ENUM ('PENDING','ACTIVE','SUSPENDED','COMPLETED');
CREATE TYPE publication_status AS ENUM ('DRAFT','SCHEDULED','PUBLISHED','CLOSED','CANCELLED');
CREATE TYPE task_assignment_status AS ENUM ('PENDING','SUBMITTED');
CREATE TYPE attendance_status AS ENUM ('PRESENT','LATE','ABSENT');
CREATE TYPE meal_status AS ENUM ('GOOD','FAIR','DID_NOT_EAT');
CREATE TYPE mood_status AS ENUM ('HAPPY','CHEERFUL','SAD','ANGRY');
CREATE TYPE event_type AS ENUM ('MEETING','ACTIVITY','REMINDER','SUBMISSION');
CREATE TYPE recipient_type AS ENUM ('INSTITUTION','GROUP','STUDENT','USER');

CREATE TABLE institutions (
  id uuid PRIMARY KEY,
  name text NOT NULL CHECK (length(trim(name)) BETWEEN 2 AND 180),
  code text NOT NULL UNIQUE,
  status institution_status NOT NULL DEFAULT 'ACTIVE',
  time_zone text NOT NULL DEFAULT 'America/Panama',
  contact_email text,
  contact_phone text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE users (
  id uuid PRIMARY KEY,
  name text NOT NULL,
  last_name text NOT NULL,
  email text NOT NULL,
  phone text,
  status account_status NOT NULL DEFAULT 'INVITED',
  must_change_password boolean NOT NULL DEFAULT true,
  terms_accepted boolean NOT NULL DEFAULT false,
  preferred_language text NOT NULL DEFAULT 'es' CHECK (preferred_language IN ('es','en')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  CONSTRAINT users_email_normalized CHECK (email = lower(trim(email))),
  CONSTRAINT users_email_format CHECK (position('@' in email) > 1)
);
CREATE UNIQUE INDEX ux_users_active_email ON users(email) WHERE deleted_at IS NULL;
CREATE INDEX ix_users_status ON users(status) WHERE deleted_at IS NULL;

CREATE TABLE credentials (
  user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  password_hash text NOT NULL,
  algorithm text NOT NULL DEFAULT 'argon2id',
  password_updated_at timestamptz NOT NULL DEFAULT now(),
  last_login_at timestamptz,
  failed_attempts integer NOT NULL DEFAULT 0 CHECK (failed_attempts >= 0),
  locked_until timestamptz,
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE institution_memberships (
  id uuid PRIMARY KEY,
  institution_id uuid NOT NULL REFERENCES institutions(id),
  user_id uuid NOT NULL REFERENCES users(id),
  status membership_status NOT NULL DEFAULT 'PENDING',
  start_date date,
  end_date date,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (institution_id, user_id),
  UNIQUE (id, institution_id),
  CHECK (end_date IS NULL OR start_date IS NULL OR end_date >= start_date)
);
CREATE INDEX ix_memberships_user ON institution_memberships(user_id, status);

CREATE TABLE roles (
  id uuid PRIMARY KEY,
  code text NOT NULL UNIQUE,
  name text NOT NULL,
  scope text NOT NULL CHECK (scope IN ('GLOBAL','INSTITUTION')),
  description text
);
CREATE TABLE permissions (
  id uuid PRIMARY KEY,
  code text NOT NULL UNIQUE,
  description text NOT NULL
);
CREATE TABLE role_permissions (
  role_id uuid NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
  permission_id uuid NOT NULL REFERENCES permissions(id) ON DELETE CASCADE,
  PRIMARY KEY (role_id, permission_id)
);
CREATE TABLE user_roles (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role_id uuid NOT NULL REFERENCES roles(id),
  institution_id uuid REFERENCES institutions(id),
  assigned_by uuid REFERENCES users(id),
  assigned_at timestamptz NOT NULL DEFAULT now(),
  revoked_at timestamptz
);
CREATE UNIQUE INDEX ux_user_role_institution_active
  ON user_roles(user_id, role_id, COALESCE(institution_id, '00000000-0000-0000-0000-000000000000'::uuid))
  WHERE revoked_at IS NULL;
CREATE INDEX ix_user_roles_user ON user_roles(user_id) WHERE revoked_at IS NULL;

CREATE TABLE password_reset_tokens (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash text NOT NULL UNIQUE,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  used_at timestamptz,
  revoked_at timestamptz,
  request_ip inet,
  CHECK (expires_at > created_at)
);
CREATE INDEX ix_password_reset_user ON password_reset_tokens(user_id, expires_at DESC);

CREATE TABLE refresh_sessions (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash text NOT NULL UNIQUE,
  family_id uuid NOT NULL,
  client_type text NOT NULL CHECK (client_type IN ('ANDROID','WEB')),
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  last_used_at timestamptz,
  revoked_at timestamptz,
  replaced_session_id uuid REFERENCES refresh_sessions(id),
  user_agent text,
  ip_address inet,
  CHECK (expires_at > created_at)
);
CREATE INDEX ix_refresh_sessions_user ON refresh_sessions(user_id, expires_at DESC);
CREATE INDEX ix_refresh_sessions_family ON refresh_sessions(family_id);

CREATE TABLE terms_and_conditions (
  id uuid PRIMARY KEY,
  version text NOT NULL UNIQUE,
  title text NOT NULL,
  content text NOT NULL,
  language text NOT NULL DEFAULT 'es' CHECK (language IN ('es','en')),
  published_at timestamptz,
  is_current boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX ux_current_terms_language ON terms_and_conditions(language) WHERE is_current;
CREATE TABLE terms_acceptances (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id),
  terms_id uuid NOT NULL REFERENCES terms_and_conditions(id),
  accepted_at timestamptz NOT NULL DEFAULT now(),
  ip_address inet,
  user_agent text,
  UNIQUE (user_id, terms_id)
);

CREATE TABLE students (
  id uuid PRIMARY KEY,
  institution_id uuid NOT NULL REFERENCES institutions(id),
  internal_code text,
  name text NOT NULL,
  last_name text NOT NULL,
  birth_date date,
  allergies text,
  relevant_conditions text,
  status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE','GRADUATED')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (id, institution_id),
  UNIQUE (institution_id, internal_code),
  CHECK (birth_date IS NULL OR birth_date <= CURRENT_DATE)
);
CREATE INDEX ix_students_institution_name ON students(institution_id, last_name, name);

CREATE TABLE student_guardians (
  id uuid PRIMARY KEY,
  institution_id uuid NOT NULL REFERENCES institutions(id),
  guardian_user_id uuid NOT NULL REFERENCES users(id),
  student_id uuid NOT NULL,
  relationship text,
  is_primary boolean NOT NULL DEFAULT false,
  can_receive_notifications boolean NOT NULL DEFAULT true,
  status membership_status NOT NULL DEFAULT 'ACTIVE',
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (student_id, institution_id) REFERENCES students(id, institution_id),
  UNIQUE (guardian_user_id, student_id),
  UNIQUE (id, institution_id)
);
CREATE UNIQUE INDEX ux_primary_guardian_student ON student_guardians(student_id) WHERE is_primary AND status = 'ACTIVE';
CREATE INDEX ix_guardians_student ON student_guardians(student_id, status);
CREATE INDEX ix_guardians_user ON student_guardians(guardian_user_id, status);

CREATE TABLE grade_levels (
  id uuid PRIMARY KEY,
  institution_id uuid NOT NULL REFERENCES institutions(id),
  name text NOT NULL,
  sort_order smallint NOT NULL DEFAULT 0,
  UNIQUE (institution_id, name),
  UNIQUE (id, institution_id)
);
CREATE TABLE academic_periods (
  id uuid PRIMARY KEY,
  institution_id uuid NOT NULL REFERENCES institutions(id),
  name text NOT NULL,
  start_date date NOT NULL,
  end_date date NOT NULL,
  status text NOT NULL DEFAULT 'PLANNED' CHECK (status IN ('PLANNED','ACTIVE','CLOSED')),
  UNIQUE (id, institution_id),
  UNIQUE (institution_id, name),
  CHECK (end_date >= start_date)
);
CREATE TABLE groups (
  id uuid PRIMARY KEY,
  institution_id uuid NOT NULL REFERENCES institutions(id),
  grade_id uuid NOT NULL,
  academic_period_id uuid NOT NULL,
  name text NOT NULL,
  status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE','CLOSED')),
  FOREIGN KEY (grade_id, institution_id) REFERENCES grade_levels(id, institution_id),
  FOREIGN KEY (academic_period_id, institution_id) REFERENCES academic_periods(id, institution_id),
  UNIQUE (id, institution_id),
  UNIQUE (institution_id, academic_period_id, name)
);
CREATE TABLE enrollments (
  id uuid PRIMARY KEY,
  institution_id uuid NOT NULL REFERENCES institutions(id),
  student_id uuid NOT NULL,
  group_id uuid NOT NULL,
  start_date date NOT NULL,
  end_date date,
  status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','WITHDRAWN','COMPLETED')),
  FOREIGN KEY (student_id, institution_id) REFERENCES students(id, institution_id),
  FOREIGN KEY (group_id, institution_id) REFERENCES groups(id, institution_id),
  CHECK (end_date IS NULL OR end_date >= start_date),
  UNIQUE (id, institution_id)
);
CREATE UNIQUE INDEX ux_active_enrollment_student ON enrollments(student_id) WHERE status = 'ACTIVE';
CREATE INDEX ix_enrollments_group ON enrollments(group_id, status);

CREATE TABLE subjects (
  id uuid PRIMARY KEY,
  institution_id uuid NOT NULL REFERENCES institutions(id),
  code text,
  name text NOT NULL,
  description text,
  is_active boolean NOT NULL DEFAULT true,
  UNIQUE (id, institution_id),
  UNIQUE (institution_id, name),
  UNIQUE (institution_id, code)
);
CREATE TABLE teaching_assignments (
  id uuid PRIMARY KEY,
  institution_id uuid NOT NULL REFERENCES institutions(id),
  teacher_user_id uuid NOT NULL REFERENCES users(id),
  group_id uuid NOT NULL,
  subject_id uuid,
  academic_period_id uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (group_id, institution_id) REFERENCES groups(id, institution_id),
  FOREIGN KEY (subject_id, institution_id) REFERENCES subjects(id, institution_id),
  FOREIGN KEY (academic_period_id, institution_id) REFERENCES academic_periods(id, institution_id),
  UNIQUE (id, institution_id),
  UNIQUE NULLS NOT DISTINCT (teacher_user_id, group_id, subject_id, academic_period_id)
);
CREATE INDEX ix_teaching_assignments_teacher ON teaching_assignments(teacher_user_id, institution_id);

CREATE TABLE assessments (
  id uuid PRIMARY KEY,
  institution_id uuid NOT NULL REFERENCES institutions(id),
  teaching_assignment_id uuid NOT NULL,
  title text NOT NULL,
  description text,
  max_score numeric(8,2) NOT NULL CHECK (max_score > 0),
  assessment_date date,
  created_by uuid NOT NULL REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (teaching_assignment_id, institution_id) REFERENCES teaching_assignments(id, institution_id),
  UNIQUE (id, institution_id)
);
CREATE TABLE grade_records (
  id uuid PRIMARY KEY,
  institution_id uuid NOT NULL REFERENCES institutions(id),
  assessment_id uuid NOT NULL,
  student_id uuid NOT NULL,
  score numeric(8,2) NOT NULL CHECK (score >= 0),
  comment text,
  published_at timestamptz,
  recorded_by uuid NOT NULL REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (assessment_id, institution_id) REFERENCES assessments(id, institution_id),
  FOREIGN KEY (student_id, institution_id) REFERENCES students(id, institution_id),
  UNIQUE (assessment_id, student_id),
  UNIQUE (id, institution_id)
);
CREATE INDEX ix_grade_records_student ON grade_records(student_id, assessment_id);
CREATE INDEX ix_published_grade_records ON grade_records(student_id, published_at DESC)
  WHERE published_at IS NOT NULL;

-- Per-guardian reads support the Home new-grade counter.
-- Manual publication: published_at remains NULL until publication.
-- Editing an already-published grade updates the content without clearing published_at;
-- the updated grade becomes visible immediately after saving.
CREATE TABLE grade_reads (
  grade_record_id uuid NOT NULL,
  institution_id uuid NOT NULL,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  read_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (grade_record_id, user_id),
  FOREIGN KEY (grade_record_id, institution_id)
    REFERENCES grade_records(id, institution_id) ON DELETE CASCADE
);
CREATE INDEX ix_grade_reads_user ON grade_reads(user_id, read_at DESC);

CREATE TABLE tasks (
  id uuid PRIMARY KEY,
  institution_id uuid NOT NULL REFERENCES institutions(id),
  teaching_assignment_id uuid NOT NULL,
  title text NOT NULL,
  description text,
  due_at timestamptz,
  publication_status publication_status NOT NULL DEFAULT 'DRAFT',
  publish_at timestamptz,
  published_at timestamptz,
  created_by uuid NOT NULL REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (teaching_assignment_id, institution_id) REFERENCES teaching_assignments(id, institution_id),
  UNIQUE (id, institution_id)
);
CREATE TABLE task_recipients (
  id uuid PRIMARY KEY,
  institution_id uuid NOT NULL REFERENCES institutions(id),
  task_id uuid NOT NULL,
  group_id uuid,
  student_id uuid,
  FOREIGN KEY (task_id, institution_id) REFERENCES tasks(id, institution_id) ON DELETE CASCADE,
  FOREIGN KEY (group_id, institution_id) REFERENCES groups(id, institution_id),
  FOREIGN KEY (student_id, institution_id) REFERENCES students(id, institution_id),
  CHECK ((group_id IS NOT NULL) <> (student_id IS NOT NULL)),
  UNIQUE NULLS NOT DISTINCT (task_id, group_id, student_id)
);
CREATE TABLE task_assignments (
  id uuid PRIMARY KEY,
  institution_id uuid NOT NULL REFERENCES institutions(id),
  task_id uuid NOT NULL,
  student_id uuid NOT NULL,
  status task_assignment_status NOT NULL DEFAULT 'PENDING',
  submitted_at timestamptz,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid REFERENCES users(id),
  FOREIGN KEY (task_id, institution_id) REFERENCES tasks(id, institution_id) ON DELETE CASCADE,
  FOREIGN KEY (student_id, institution_id) REFERENCES students(id, institution_id),
  UNIQUE (task_id, student_id),
  UNIQUE (id, institution_id),
  CHECK (
    (status = 'PENDING' AND submitted_at IS NULL) OR
    (status = 'SUBMITTED' AND submitted_at IS NOT NULL)
  )
);
CREATE INDEX ix_tasks_status_due_date ON tasks(institution_id, publication_status, due_at);
CREATE INDEX ix_task_assignments_student ON task_assignments(student_id, status);

CREATE TABLE attendance_records (
  id uuid PRIMARY KEY,
  institution_id uuid NOT NULL REFERENCES institutions(id),
  student_id uuid NOT NULL,
  group_id uuid NOT NULL,
  record_date date NOT NULL,
  status attendance_status NOT NULL,
  notes text,
  recorded_by uuid NOT NULL REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (student_id, institution_id) REFERENCES students(id, institution_id),
  FOREIGN KEY (group_id, institution_id) REFERENCES groups(id, institution_id),
  UNIQUE (student_id, record_date),
  UNIQUE (id, institution_id)
);
CREATE INDEX ix_attendance_group_date ON attendance_records(group_id, record_date);

CREATE TABLE daily_tracking (
  id uuid PRIMARY KEY,
  institution_id uuid NOT NULL REFERENCES institutions(id),
  student_id uuid NOT NULL,
  group_id uuid NOT NULL,
  record_date date NOT NULL,
  meal_status meal_status,
  mood_status mood_status,
  notes text,
  recorded_by uuid NOT NULL REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (student_id, institution_id) REFERENCES students(id, institution_id),
  FOREIGN KEY (group_id, institution_id) REFERENCES groups(id, institution_id),
  UNIQUE (student_id, record_date)
);

CREATE TABLE announcements (
  id uuid PRIMARY KEY,
  institution_id uuid NOT NULL REFERENCES institutions(id),
  title text NOT NULL,
  message_body text NOT NULL,
  publication_status publication_status NOT NULL DEFAULT 'DRAFT',
  publish_at timestamptz,
  published_at timestamptz,
  created_by uuid NOT NULL REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (id, institution_id)
);
CREATE TABLE announcement_recipients (
  id uuid PRIMARY KEY,
  institution_id uuid NOT NULL REFERENCES institutions(id),
  announcement_id uuid NOT NULL,
  recipient_type recipient_type NOT NULL,
  group_id uuid,
  student_id uuid,
  user_id uuid REFERENCES users(id),
  FOREIGN KEY (announcement_id, institution_id) REFERENCES announcements(id, institution_id) ON DELETE CASCADE,
  FOREIGN KEY (group_id, institution_id) REFERENCES groups(id, institution_id),
  FOREIGN KEY (student_id, institution_id) REFERENCES students(id, institution_id),
  CHECK (
    (recipient_type = 'INSTITUTION' AND group_id IS NULL AND student_id IS NULL AND user_id IS NULL) OR
    (recipient_type = 'GROUP' AND group_id IS NOT NULL AND student_id IS NULL AND user_id IS NULL) OR
    (recipient_type = 'STUDENT' AND group_id IS NULL AND student_id IS NOT NULL AND user_id IS NULL) OR
    (recipient_type = 'USER' AND group_id IS NULL AND student_id IS NULL AND user_id IS NOT NULL)
  )
);
CREATE TABLE events (
  id uuid PRIMARY KEY,
  institution_id uuid NOT NULL REFERENCES institutions(id),
  title text NOT NULL,
  description text,
  event_type event_type NOT NULL,
  starts_at timestamptz NOT NULL,
  ends_at timestamptz,
  location text,
  publication_status publication_status NOT NULL DEFAULT 'DRAFT',
  publish_at timestamptz,
  created_by uuid NOT NULL REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (ends_at IS NULL OR ends_at >= starts_at),
  UNIQUE (id, institution_id)
);
CREATE TABLE event_recipients (
  id uuid PRIMARY KEY,
  institution_id uuid NOT NULL REFERENCES institutions(id),
  event_id uuid NOT NULL,
  recipient_type recipient_type NOT NULL,
  group_id uuid,
  student_id uuid,
  user_id uuid REFERENCES users(id),
  FOREIGN KEY (event_id, institution_id) REFERENCES events(id, institution_id) ON DELETE CASCADE,
  FOREIGN KEY (group_id, institution_id) REFERENCES groups(id, institution_id),
  FOREIGN KEY (student_id, institution_id) REFERENCES students(id, institution_id),
  CHECK (
    (recipient_type = 'INSTITUTION' AND group_id IS NULL AND student_id IS NULL AND user_id IS NULL) OR
    (recipient_type = 'GROUP' AND group_id IS NOT NULL AND student_id IS NULL AND user_id IS NULL) OR
    (recipient_type = 'STUDENT' AND group_id IS NULL AND student_id IS NOT NULL AND user_id IS NULL) OR
    (recipient_type = 'USER' AND group_id IS NULL AND student_id IS NULL AND user_id IS NOT NULL)
  )
);
CREATE INDEX ix_events_institution_start ON events(institution_id, starts_at) WHERE publication_status = 'PUBLISHED';

-- MVP messages are one-way announcements, not conversations or chat.
CREATE TABLE messages (
  id uuid PRIMARY KEY,
  institution_id uuid NOT NULL REFERENCES institutions(id),
  title text NOT NULL,
  content text NOT NULL CHECK (length(trim(content)) > 0),
  publication_status publication_status NOT NULL DEFAULT 'DRAFT',
  publish_at timestamptz,
  published_at timestamptz,
  created_by uuid NOT NULL REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (id, institution_id)
);
CREATE INDEX ix_published_messages_institution
  ON messages(institution_id, published_at DESC)
  WHERE publication_status = 'PUBLISHED';

CREATE TABLE message_recipients (
  id uuid PRIMARY KEY,
  institution_id uuid NOT NULL REFERENCES institutions(id),
  message_id uuid NOT NULL,
  recipient_type recipient_type NOT NULL,
  group_id uuid,
  student_id uuid,
  user_id uuid REFERENCES users(id),
  FOREIGN KEY (message_id, institution_id) REFERENCES messages(id, institution_id) ON DELETE CASCADE,
  FOREIGN KEY (group_id, institution_id) REFERENCES groups(id, institution_id),
  FOREIGN KEY (student_id, institution_id) REFERENCES students(id, institution_id),
  CHECK (
    (recipient_type = 'INSTITUTION' AND group_id IS NULL AND student_id IS NULL AND user_id IS NULL) OR
    (recipient_type = 'GROUP' AND group_id IS NOT NULL AND student_id IS NULL AND user_id IS NULL) OR
    (recipient_type = 'STUDENT' AND group_id IS NULL AND student_id IS NOT NULL AND user_id IS NULL) OR
    (recipient_type = 'USER' AND group_id IS NULL AND student_id IS NULL AND user_id IS NOT NULL)
  )
);
CREATE INDEX ix_message_recipients_message ON message_recipients(message_id);
CREATE INDEX ix_message_recipients_group ON message_recipients(institution_id, group_id)
  WHERE recipient_type = 'GROUP';
CREATE INDEX ix_message_recipients_student ON message_recipients(institution_id, student_id)
  WHERE recipient_type = 'STUDENT';
CREATE INDEX ix_message_recipients_user ON message_recipients(user_id)
  WHERE recipient_type = 'USER';

-- One read per user and message (not per student).
-- Home filters messages by the selected student and applicable audience;
-- reading an applicable message records the read for that user.
CREATE TABLE message_reads (
  message_id uuid NOT NULL,
  institution_id uuid NOT NULL,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  read_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (message_id, user_id),
  FOREIGN KEY (message_id, institution_id) REFERENCES messages(id, institution_id) ON DELETE CASCADE
);
CREATE INDEX ix_message_reads_user ON message_reads(user_id, read_at DESC);

CREATE TABLE notifications (
  id uuid PRIMARY KEY,
  institution_id uuid REFERENCES institutions(id),
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  notification_type text NOT NULL,
  title text NOT NULL,
  body text NOT NULL,
  entity_type text,
  entity_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  read_at timestamptz,
  delivered_at timestamptz
);
CREATE INDEX ix_unread_notifications_user ON notifications(user_id, created_at DESC) WHERE read_at IS NULL;

-- MVP contact details are stored on institutions as contact_email and contact_phone.
-- MIMU contact details are configured in the application/platform, not as support tickets.
-- Advanced audit, push devices, and outbox are deferred from the active MVP schema.

-- No demo data or role/permission seeds are included in this version.
-- UUIDv7 IDs must be generated by the API/application; the database does not generate IDs.
-- Required role codes: PARENT_GUARDIAN, TEACHER, SCHOOL_ADMIN, MIMU_SUPPORT_ADMIN.
-- MIMU_SUPPORT_ADMIN is global; other roles are institution-scoped.
-- The API must validate role scope and resource ownership on every request.

COMMIT;
